// Each pattern in ~30 lines — see Building Effective Agents.
import Anthropic from '@anthropic-ai/sdk';
const client = new Anthropic();
const MODEL = 'claude-sonnet-4-5';

async function llm(prompt: string, system?: string) {
  const r = await client.messages.create({
    model: MODEL,
    max_tokens: 1024,
    system,
    messages: [{ role: 'user', content: prompt }],
  });
  return r.content.filter(b => b.type === 'text').map(b => (b as { text: string }).text).join('');
}

// 1. Chaining
export async function chain(input: string) {
  const a = await llm(`Outline a blog post about: ${input}`);
  if (!a.includes('-')) throw new Error('Outline gate failed');
  const b = await llm(`Draft the post from this outline:\n${a}`);
  return llm(`Polish for tone and grammar:\n${b}`);
}

// 2. Routing
export async function route(query: string) {
  const label = (await llm(
    `Classify the query into one of: billing | tech | general.\nQuery: ${query}\nReturn only the label.`,
  )).trim().toLowerCase();
  if (label === 'billing') return llm(query, 'You are a billing specialist.');
  if (label === 'tech') return llm(query, 'You are a senior engineer.');
  return llm(query);
}

// 3. Parallelization (voting)
export async function vote(prompt: string) {
  const variants = await Promise.all([0.3, 0.7, 1.0].map(t =>
    client.messages.create({ model: MODEL, max_tokens: 512, temperature: t, messages: [{ role: 'user', content: prompt }] }),
  ));
  const answers = variants.map(v => v.content.filter(b => b.type === 'text').map(b => (b as { text: string }).text).join(''));
  return llm(`Three candidate answers:\n${answers.map((a, i) => `(${i + 1}) ${a}`).join('\n')}\nReturn the best one.`);
}

// 4. Orchestrator-workers
export async function orchestrate(goal: string) {
  const plan = JSON.parse(await llm(
    `Goal: ${goal}\nReturn a JSON array of independent sub-tasks. Format: [{\"id\": string, \"task\": string}]`,
  ));
  const results = await Promise.all(plan.map((s: { task: string }) => llm(s.task)));
  return llm(`Synthesize a final answer from these sub-results:\n${results.join('\n---\n')}`);
}

// 5. Evaluator-optimizer
export async function evalLoop(prompt: string, max = 3) {
  let draft = await llm(prompt);
  for (let i = 0; i < max; i++) {
    const verdict = await llm(`Grade this draft on accuracy + clarity. Return PASS or REVISE: <why>.\nDraft:\n${draft}`);
    if (verdict.startsWith('PASS')) return draft;
    draft = await llm(`Revise the draft using this feedback:\n${verdict}\n\nOriginal:\n${draft}`);
  }
  return draft;
}
